begin;
do $review$
declare w public.hb_workflow_templates%rowtype; reviewed timestamptz:=now();
begin
 select * into strict w from public.hb_workflow_templates where workflow_key='service:umm-al-quwain-trade-name-official-path' and status='active' for update;
 if w.version=2 and w.definition->>'source'='https://ded.uaq.ae/en/our-activities/service/bookingtradename.html' then return;end if;
 if w.version<>1 or w.definition->>'source'<>'https://u.ae/en/information-and-services/business/important-digital-services/inquire-about-licences-names-and-activities' then raise exception 'UAQ workflow changed; re-review';end if;
 update public.hb_workflow_templates set status='retired',effective_until=reviewed where id=w.id;
 insert into public.hb_workflow_templates(workflow_key,jurisdiction_id,service_slug,version,status,definition,effective_from,country_pack_id) values(w.workflow_key,w.jurisdiction_id,w.service_slug,2,'active',$definition${"id":"service:umm-al-quwain-trade-name-official-path","steps":[{"key":"intake","title":"تأكيد بيانات الطلب والحالة","metadata":{"agent":"intake"},"taskType":"intake","assigneeType":"agent"},{"key":"requirement-1","title":"للمواطن أو مواطن مجلس التعاون: أصل الهوية وصورة جواز السفر والبريد الإلكتروني ورقم الهاتف لصاحب الرخصة.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-2","title":"للمدير المسؤول الوافد: أصل الهوية وصورة جواز السفر والإقامة والبريد الإلكتروني ورقم الهاتف.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-3","title":"خطاب عدم ممانعة مصدق من الكفيل أو صورة رخصة المستثمر بحسب الحالات المحددة في البطاقة، مع متطلبات إضافية لمدير الفرع عند اختلافه.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-4","title":"ثلاثة أسماء تجارية مكتوبة تدل على النشاط بالعربية ومترجمة إلى الإنجليزية.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-5","title":"وكالة عند غياب صاحب العلاقة.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-6","title":"طباعة الأنشطة المطلوبة والبريد الإلكتروني ورقم الهاتف المتعلقين بالرخصة.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"requirement-7","title":"تحديد ما إذا كانت الرخصة تتبع برنامج الشيخ سعود لمشاريع الشباب.","metadata":{"source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"},"taskType":"requirement","dependsOn":["intake"],"assigneeType":"user"},{"key":"quality-review","title":"مراجعة اكتمال المستندات والمتطلبات","metadata":{"agent":"quality","conditions":"تختلف المستندات بحسب الجنسية وصفة المدير والفرع والتمثيل بوكالة؛ راجع الحالات المحددة في بطاقة الدائرة. حجز الاسم التجاري لا يمثل إصدار الرخصة. تذكر خانة الرسوم «حسب الطلب» دون مبلغ، ولا تُنشر مدة إنجاز محددة؛ أكد المبلغ والمدة مع الدائرة."},"taskType":"review","dependsOn":["requirement-1","requirement-2","requirement-3","requirement-4","requirement-5","requirement-6","requirement-7"],"assigneeType":"agent"},{"key":"execution-approval","title":"اعتماد الانتقال إلى مسار التنفيذ","metadata":{"officialUrl":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html","executionMode":"guidance"},"taskType":"approval","dependsOn":["quality-review"],"assigneeType":"user","requiresApproval":true},{"key":"external-execution","title":"تنفيذ أو متابعة الإجراء لدى الجهة المختصة","metadata":{"authority":"uaq-business","officialUrl":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html","executionMode":"guidance"},"taskType":"external","dependsOn":["execution-approval"],"assigneeType":"integration","requiresApproval":true},{"key":"completion","title":"توثيق النتيجة وإغلاق المعاملة","taskType":"completion","dependsOn":["external-execution"],"assigneeType":"system"}],"title":"المسار الرسمي لحجز اسم تجاري في أم القيوين","source":"https://ded.uaq.ae/en/our-activities/service/bookingtradename.html","version":2}$definition$::jsonb,reviewed,w.country_pack_id);
end $review$;
commit;
